const express = require('express');
const Joi = require('joi');
const request = require('supertest'); // for testing within the same process

// Initialize app
const app = express();
app.use(express.json());

// In‑memory data store
let users = [
  { id: 1, name: 'Tony Stark', email: 'tony@stark.com' },
  { id: 2, name: 'Bruce Banner', email: 'bruce@avengers.com' }
];
let nextId = 3;

// Validation schemas
const userSchema = Joi.object({
  name: Joi.string().min(3).max(50).required(),
  email: Joi.string().email().required()
});
const idParamSchema = Joi.object({
  id: Joi.number().integer().min(1).required()
});

// Middleware factory
function validate(schema, source = 'body') {
  return (req, res, next) => {
    const { error, value } = schema.validate(req[source], { abortEarly: false });
    if (error) {
      return res.status(400).json({
        error: 'Validation Failed',
        details: error.details.map(d => d.message)
      });
    }
    req[source] = value; // sanitized/coerced data
    next();
  };
}

// Routes
app.get('/users', (req, res) => {
  res.json(users);
});

app.get('/users/:id', validate(idParamSchema, 'params'), (req, res) => {
  const user = users.find(u => u.id === req.params.id);
  if (!user) return res.status(404).json({ error: 'User not found' });
  res.json(user);
});

app.post('/users', validate(userSchema), (req, res) => {
  const { name, email } = req.body;
  if (users.some(u => u.email === email)) {
    return res.status(409).json({ error: 'Email already exists' });
  }
  const newUser = { id: nextId++, name, email };
  users.push(newUser);
  res.status(201).json(newUser);
});

